﻿import Network from '../../../src/architecture/network/network';
import { Activation } from '../../../src/methods/activation/activation';
import {
  evaluateConcurrentRacingAgents,
  type RacingAgentRequest,
} from '../../../src/architecture/network/gpu/network.gpu.racing';
import { createConcurrentBufferSet } from '../../../src/architecture/network/gpu/network.gpu.buffer';

/**
 * Symbol key used by the worker-compatible activation registry.
 */
const ACTIVATION_KEY_SYMBOL = Symbol.for('neataptic.activation.key');

/**
 * Number of concurrent racing requests to issue against the same network instance.
 */
const REQUEST_COUNT = 8;

/**
 * Create a worker-registry-compatible logistic activation wrapper.
 *
 * The GPU path resolves activations by symbol key, name, or behaviour match.
 * This wrapper delegates to the public logistic function while tagging itself
 * with the worker key so the kernel compiler can find the correct switch index.
 */
function makeGPULogisticActivation(): (x: number, derivate?: boolean) => number {
  const workerKey = 'logisticActivation2';
  const fn = (x: number, derivate = false): number =>
    Activation.logistic(x, derivate);
  (fn as unknown as Record<symbol, string>)[ACTIVATION_KEY_SYMBOL] = workerKey;
  try {
    Object.defineProperty(fn, 'name', { value: workerKey, configurable: true });
  } catch {
    // Some environments disallow name redefinition; the symbol key is enough.
  }
  return fn;
}

/**
 * Read WebGPU adapter metadata in a cross-browser way.
 */
async function readAdapterInfo(
  adapter: GPUAdapter | null | undefined,
): Promise<Record<string, unknown> | null> {
  if (!adapter) return null;
  try {
    if (typeof adapter.requestAdapterInfo === 'function') {
      return (await adapter.requestAdapterInfo()) as Record<string, unknown>;
    }
    const info = adapter.info;
    if (info) {
      return {
        vendor: info.vendor,
        architecture: info.architecture,
        device: info.device,
        description: info.description,
      };
    }
  } catch (error) {
    return { error: String(error) };
  }
  return null;
}

/**
 * Determine whether the scenario page is running in a visible foreground window.
 *
 * GPU parity measurements are only valid when the browser window is visible and
 * in the foreground; background tabs throttle the GPU process and produce
 * unreliable numbers.
 */
function determineBrowserVisibility(): string {
  if (
    document.visibilityState === 'visible' &&
    !document.hidden &&
    document.hasFocus()
  ) {
    return 'visible-foreground';
  }
  if (document.hidden || document.visibilityState !== 'visible') {
    return 'visible-background';
  }
  return 'visible-background';
}

/**
 * Run the WebGPU concurrent racing-agent parity smoke test.
 *
 * Builds one shared MLP, issues multiple concurrent evaluation requests with
 * different inputs against the same network instance, and compares each GPU
 * output against a CPU reference computed with network.activate().
 */
export async function runWebGPURacingConcurrentSmoke(): Promise<Record<string, unknown>> {
  const startTime = performance.now();
  const browserVisibility = determineBrowserVisibility();

  try {
    // Abort early if the browser window is not a valid foreground target.
    if (browserVisibility !== 'visible-foreground') {
      return {
        success: false,
        browserVisibility,
        gpuDeviceBound: false,
        adapterInfo: null,
        maxAbsDiff: NaN,
        meanAbsDiff: NaN,
        error: 'Browser window is not visible-foreground; GPU measurement aborted.',
      };
    }

    // Step 1: build a 2-3-1 MLP and make every squash worker-compatible.
    const network = Network.createMLP(2, [3], 1);
    const gpuLogistic = makeGPULogisticActivation();
    for (const node of network.nodes) {
      if (typeof node.squash === 'function') {
        node.squash = gpuLogistic;
      }
    }

    // Step 2: acquire a WebGPU device and read adapter metadata.
    const adapter = await navigator.gpu?.requestAdapter();
    const device = await adapter?.requestDevice();
    const gpuDeviceBound = Boolean(device);
    const adapterInfo = await readAdapterInfo(adapter);

    if (!device) {
      return {
        success: false,
        browserVisibility,
        gpuDeviceBound: false,
        adapterInfo,
        maxAbsDiff: NaN,
        meanAbsDiff: NaN,
        error: 'No WebGPU device available.',
      };
    }

    // Step 3: sanity-check createConcurrentBufferSet directly.
    const freshBufferSet = createConcurrentBufferSet(device, network);
    const bufferSetKeys = [
      'connections',
      'nodes',
      'outputs',
      'params',
      'topoLevels',
      'inStart',
    ] as const;
    const bufferSetValid = bufferSetKeys.every(
      (key) => freshBufferSet[key] && typeof freshBufferSet[key].destroy === 'function',
    );
    for (const key of bufferSetKeys) {
      freshBufferSet[key].destroy();
    }
    if (!bufferSetValid) {
      return {
        success: false,
        browserVisibility,
        gpuDeviceBound,
        adapterInfo,
        maxAbsDiff: NaN,
        meanAbsDiff: NaN,
        error: 'createConcurrentBufferSet did not return a complete buffer set.',
      };
    }

    // Step 4: build concurrent requests that reuse the same network with different inputs.
    const requests: RacingAgentRequest[] = [];
    for (let i = 0; i < REQUEST_COUNT; i++) {
      requests.push({
        network,
        inputs: new Float32Array([
          0.1 + i * 0.15,
          -0.4 + i * 0.12,
        ]),
      });
    }

    // Step 5: compute CPU references.
    const cpuReferences = requests.map((request) =>
      Array.from(network.activate(request.inputs)),
    );

    // Step 6: evaluate all requests concurrently on the GPU.
    device.pushErrorScope('validation');
    const gpuOutputs = await evaluateConcurrentRacingAgents(device, requests);
    const validationError = await device.popErrorScope();

    if (validationError) {
      return {
        success: false,
        browserVisibility,
        gpuDeviceBound,
        adapterInfo,
        maxAbsDiff: NaN,
        meanAbsDiff: NaN,
        error: `WebGPU validation error: ${(validationError as Error).message ?? String(validationError)}`,
      };
    }

    // Step 7: compute parity metrics.
    let maxAbsDiff = 0;
    let totalAbsDiff = 0;
    let elementCount = 0;
    for (let i = 0; i < requests.length; i++) {
      const cpu = cpuReferences[i];
      const gpu = Array.from(gpuOutputs[i] ?? []);
      for (let j = 0; j < cpu.length; j++) {
        const diff = Math.abs(cpu[j] - (gpu[j] ?? 0));
        maxAbsDiff = Math.max(maxAbsDiff, diff);
        totalAbsDiff += diff;
        elementCount++;
      }
    }
    const meanAbsDiff = elementCount > 0 ? totalAbsDiff / elementCount : 0;

    const success =
      gpuDeviceBound &&
      maxAbsDiff < 1e-3 &&
      meanAbsDiff < 1e-4;

    return {
      success,
      browserVisibility,
      gpuDeviceBound,
      adapterInfo,
      maxAbsDiff,
      meanAbsDiff,
      requestCount: REQUEST_COUNT,
      durationMs: performance.now() - startTime,
    };
  } catch (error) {
    return {
      success: false,
      browserVisibility,
      gpuDeviceBound: false,
      adapterInfo: null,
      maxAbsDiff: NaN,
      meanAbsDiff: NaN,
      error: String(error),
    };
  }
}
